SELECT train_id AS trainId, seat_type AS seatType, COUNT(*) AS remainingTickets
FROM t_seat
WHERE start_station = #{departure}
  AND end_station = #{arrival}
  AND seat_status = 0
  AND del_flag = 0
  AND train_id IN

    #{trainId}

GROUP BY train_id, seat_type

SELECT candidate.id, candidate.train_id, candidate.carriage_number, candidate.seat_number, candidate.seat_type, candidate.start_station, candidate.end_station, candidate.price, candidate.seat_status, candidate.create_time, candidate.update_time, candidate.del_flag FROM t_seat candidate WHERE candidate.train_id = #{trainId} AND candidate.seat_type = #{seatType} AND candidate.start_station = #{affectedSegments[0].departure} AND candidate.end_station = #{affectedSegments[0].arrival} AND candidate.seat_status = 0 AND candidate.del_flag = 0 AND NOT EXISTS ( SELECT 1 FROM t_seat segment WHERE segment.train_id = candidate.train_id AND segment.carriage_number = candidate.carriage_number AND segment.seat_number = candidate.seat_number AND segment.del_flag = 0 AND segment.seat_status <> 0 AND (
(segment.start_station = #{segment.departure} AND segment.end_station = #{segment.arrival})
) ) ORDER BY candidate.carriage_number, candidate.seat_number LIMIT #{limit}

mapper.update:
UPDATE t_seat
SET seat_status = 1,
    update_time = NOW()
WHERE train_id = #{trainId}
  AND carriage_number = #{carriageNumber}
  AND seat_number = #{seatNumber}
  AND start_station = #{departure}
  AND end_station = #{arrival}
  AND seat_status = 0
  AND del_flag = 0

UPDATE t_seat
SET seat_status = 0,
    update_time = NOW()
WHERE train_id = #{trainId}
  AND carriage_number = #{carriageNumber}
  AND seat_number = #{seatNumber}
  AND start_station = #{departure}
  AND end_station = #{arrival}
  AND seat_status = 1
  AND del_flag = 0
